using Microsoft.Azure.Functions.Worker;
using Microsoft.Extensions.Logging;

public class DocumentIngestionFunctions
{
    private readonly IDocumentParsingService _parser;
    private readonly ILogger<DocumentIngestionFunctions> _logger;

    public DocumentIngestionFunctions(IDocumentParsingService parser, ILogger<DocumentIngestionFunctions> logger)
    {
        _parser = parser;
        _logger = logger;
    }

    [Function("OnDocumentUploaded")]
    [ServiceBusOutput("pending-embeddings-queue", Connection = "ServiceBusConnection")]
    public async Task<string> Run(
        [BlobTrigger("incoming-documents/{name}", Connection = "StorageConnection")] Stream documentStream,
        string name,
        FunctionContext context)
    {
        _logger.LogInformation("Processing uploaded document: {FileName}", name);

        // Parse document stream into structured text
        var parsedText = await _parser.ExtractTextAsync(documentStream);
        _logger.LogInformation("Extracted {Length} chars from {FileName}", parsedText.Length, name);

        // Output payload is automatically serialized and dispatched to Service Bus queue
        return JsonSerializer.Serialize(new IngestionJobMessage(name, parsedText));
    }
}

public record IngestionJobMessage(string DocumentName, string Content);
